$draft = Get-Content -LiteralPath 'workflow/requirements/acceptance-draft.md' -Raw
$specLines = Get-Content -LiteralPath 'spec/requirement.md'
$quotes = [regex]::Matches($draft, 'spec/requirement\.md:L([0-9]+)；原文：([^\r\n]+)')
$mismatches = @()
foreach ($quote in $quotes) {
  $lineNumber = [int]$quote.Groups[1].Value
  $textValue = $quote.Groups[2].Value
  if (-not $specLines[$lineNumber-1].Contains($textValue)) { $mismatches += $lineNumber }
}
[ordered]@{ literal_quotes = $quotes.Count; mismatches = $mismatches } | ConvertTo-Json -Compress

